      "ref": "[D522]",
      "area": "contact",
      "claim": "A parent reports that direct messages and party chats can be disabled with parental controls.",
      "stance": "mitigation",
      "quote": "Direct messages and party chats can be disabled with parental controls."
    },
    {
      "ref": "[D522]",
      "area": "contact",
      "claim": "A parent reports that chats built into the coding of specific mini-games cannot be disabled.",
      "stance": "risk",
      "quote": "Chats built into the coding of specific mini-games cannot be disabled, and kids can type text on \"signs\" regardless of communication preferences."
    },
    {
      "ref": "[D522]",
      "area": "age_gating",
      "claim": "A parent reports that the age gate can be bypassed by mistakes in AI-based age estimation, potentially loosening protections for younger users.",
      "stance": "risk",
      "quote": "Roblox uses AI-based age estimation and verification systems for some users. Users over age 13 may be asked to submit a live selfie or upload a government ID to access certain communication features. Roblox uses this information to estimate or verify a user’s age and place accounts into age-based categories. Under Roblox’s newer system, users age 5 to 8 may be placed into “Roblox Kids” accounts, while users age 9 to 15 may be placed into “Roblox Select” accounts. However, the system can make mistakes. Incorrect age estimates may loosen built-in protections, such as chat restrictions or access limits, while some adults may be incorrectly categorized as younger users and face additional restrictions."
    },
    {
      "ref": "[D522]",
      "area": "content",
      "claim": "A parent reports that extreme violence, inappropriate language, and sexually explicit content is possible and likely within user-created games.",
      "stance": "risk",
      "quote": "Extreme violence, inappropriate language, and sexually explicit content is possible (and quite likely) within the user-created games."
    },
    {
      "ref": "[D522]",
      "area": "money",
      "claim": "A parent reports that the platform uses Robux, a digital currency, to access gated extras and includes ads and product placements.",
      "stance": "risk",
      "quote": "Key elements of the games include ads, official product placements, and the need for Robux, the platform's digital currency, to access gated extras."
    },
    {
      "ref": "[D522]",
      "area": "data",
      "claim": "A parent reports that images used for age verification may be processed by third-party providers, but Roblox does not guarantee a fixed retention period for the images of children.",
      "stance": "risk",
      "quote": "Images used for age verification may be processed by third-party providers, but Roblox does not publicly guarantee a fixed retention period for the images of children."
    }
  ]
}
